const raw = $input.first().json;
const envelope = raw.body || raw;

if (envelope.event && envelope.event !== 'messages.upsert') {
  return [{ json: { ignorar: true, razon: 'evento: ' + envelope.event } }];
}

const p = envelope.data || {};
const key = p.key || {};

if (key.fromMe === true) return [{ json: { ignorar: true, razon: 'fromMe' } }];
if ((key.remoteJid || '').includes('@g.us')) return [{ json: { ignorar: true, razon: 'es_grupo' } }];

const msg = p.message || {};
const texto = msg.conversation || msg.extendedTextMessage?.text || msg.imageMessage?.caption || '';
if (!texto.trim()) return [{ json: { ignorar: true, razon: 'sin_texto' } }];

const remoteJid = key.remoteJid || '';
const numero = remoteJid.replace('@s.whatsapp.net', '').replace('@lid', '');
if (!numero) return [{ json: { ignorar: true, razon: 'sin_numero' } }];

const msgId = key.id || '';

return [{ json: {
  ignorar: false,
  numero,
  remoteJid,
  msgId,
  nombre: p.pushName || '',
  texto: texto.trim(),
  timestamp: p.messageTimestamp || Math.floor(Date.now() / 1000)
} }];

const input = $input.first().json;
const numero = input.numero;

let sesion = null;
try {
  const raw = input.value || input[Object.keys(input).find(k => k !== 'numero' && k !== 'remoteJid' && k !== 'msgId' && k !== 'nombre' && k !== 'texto' && k !== 'timestamp' && k !== 'ignorar')];
  if (raw && typeof raw === 'string') {
    sesion = JSON.parse(raw);
  }
} catch(e) {
  sesion = null;
}

const datosMensaje = $('¿Ignorar mensaje?').item.json;

const cliente = sesion || {
  numero,
  historial: [],
  etapa: 'inicio',
  pedido: {
    productos: [],
    total: 0,
    entrega: '',
    nombre_cliente: '',
    direccion: '',
    referencia: '',
    con_cuanto_paga: 0
  }
};

if (!cliente.etapa) cliente.etapa = 'inicio';

return [{
  json: {
    ...datosMensaje,
    historial: cliente.historial,
    pedido: cliente.pedido,
    etapa: cliente.etapa
  }
}];

const geminiResponse = $input.first().json;
const datosCliente = $('Armar prompt para Gemini').item.json;

const textoCompleto = geminiResponse?.choices?.[0]?.message?.content || '';

const matchPedido = textoCompleto.match(/##PEDIDO##\s*([\s\S]*?)\s*(?:##|$)/);

let pedidoJSON = null;
let mensajeCliente = textoCompleto.replace(/\s*##PEDIDO##[\s\S]*/g, '').trim();
mensajeCliente = mensajeCliente.replace(/##MENU##/g, '').trim();

if (matchPedido) {
  try {
    pedidoJSON = JSON.parse(matchPedido[1]);
    pedidoJSON.numero_whatsapp = datosCliente.numero;
    pedidoJSON.telefono = pedidoJSON.telefono || datosCliente.numero.replace('521','').slice(-10);
    pedidoJSON.timestamp = new Date().toISOString();
  } catch (e) {
    pedidoJSON = null;
  }
}

if (mensajeCliente.includes('##PEDIDO##')) {
  mensajeCliente = mensajeCliente.split('##PEDIDO##')[0].trim();
}

return [{
  json: {
    ...datosCliente,
    respuestBot: mensajeCliente,
    pedidoCerrado: pedidoJSON !== null,
    mostrarMenu: textoCompleto.includes('##MENU##'),
    pedidoJSON
  }
}];

const datos = $('Procesar respuesta Gemini').item.json;

const historialPrevio = datos.historial || [];
const pedidoPrevio = datos.pedido || { productos: [], total: 0, entrega: '', nombre_cliente: '', direccion: '', referencia: '', con_cuanto_paga: 0 };

const historialNuevo = [...historialPrevio];
historialNuevo.push({ rol: 'cliente', texto: datos.texto });
historialNuevo.push({ rol: 'bot', texto: datos.respuestBot });
const historialFinal = historialNuevo.length > 30 ? historialNuevo.slice(-30) : historialNuevo;

const pedidoFinal = (datos.pedidoCerrado && datos.pedidoJSON) ? datos.pedidoJSON : pedidoPrevio;

const resp = (datos.respuestBot || '').toLowerCase();
let etapa = datos.etapa;

if (datos.pedidoCerrado) {
  etapa = 'inicio';
} else if (resp.includes('con quién tengo el gusto')) {
  etapa = 'esperando_nombre';
} else if (resp.includes('gusta que le mostremos') || resp.includes('ya sabe lo que va a ordenar') || resp.includes('sabe qué va a ordenar')) {
  etapa = 'esperando_opcion';
} else if (resp.includes('desea agregar algo más') || resp.includes('algo más a su pedido')) {
  etapa = 'tomando_pedido';
} else if (resp.includes('pasará a recoger') || resp.includes('llevemos a domicilio')) {
  etapa = 'esperando_entrega';
} else if (resp.includes('podría dar su dirección') || resp.includes('dirección, colonia')) {
  etapa = 'esperando_direccion';
} else if (resp.includes('cantidad nos va a pagar') || resp.includes('cuánto nos va a pagar')) {
  etapa = 'esperando_pago';
} else if (resp.includes('su pedido en capriccio') || resp.includes('total a pagar') || resp.includes('confirma que todo') || resp.includes('todo está correcto') || resp.includes('¿confirma') || resp.includes('resumen de su pedido') || resp.includes('confirme su pedido') || resp.includes('resumen')) {
  etapa = 'confirmacion';
}

const sesion = {
  numero: datos.numero,
  historial: historialFinal,
  etapa,
  pedido: pedidoFinal,
  ultima_actividad: new Date().toISOString()
};

return [{ json: { ...datos, etapa, sesionJSON: JSON.stringify(sesion) } }];

