// Horario: Lunes-Domingo 10:00am - 9:00pm (UTC-6, México Centro)
const horaUTC = new Date().getUTCHours();
const minLocal = new Date().getUTCMinutes();
const horaLocal = (horaUTC - 6 + 24) % 24;

// 10:00 a 20:59 = dentro de horario (21:00 = 9pm ya cerrado)
const dentroDeHorario = horaLocal >= 10 && horaLocal < 21;

const datos = $input.first().json;
return [{ json: { ...datos, dentroDeHorario, horaLocal } }];

